using Npgsql;using SanSo.Worker;using Xunit;
namespace SanSo.Worker.Tests;
public sealed class PostgresOutboxRuntimeV2Tests
{
 [Fact]public async Task V2StoreProvesContentionRecoveryAndFailClosedDeadLetter(){var cs=Environment.GetEnvironmentVariable("SANSO_RUNTIME_POSTGRES");if(string.IsNullOrWhiteSpace(cs))return;const string a="11111111-1111-1111-1111-111111111111",b="22222222-2222-2222-2222-222222222222";var claim=Guid.NewGuid();var lease=Guid.NewGuid();var fail=Guid.NewGuid();await Seed(cs,claim,a,"NOOP_AUDIT","PENDING",-3);await Seed(cs,lease,a,"NOOP_AUDIT","PROCESSING",-2);await Seed(cs,fail,b,"SHOPEE_SYNC","PENDING",-1);await using var source=NpgsqlDataSource.Create(cs);var one=new PostgresOutboxStoreV2(source,a);var two=new PostgresOutboxStoreV2(source,a);var claimed=await Task.WhenAll(one.Claim(TimeSpan.FromMinutes(2),default),two.Claim(TimeSpan.FromMinutes(2),default));Assert.Single(claimed,x=>x?.Id==claim);var item=claimed.Single(x=>x is not null);await one.Complete(item!.Id,default);Assert.Equal(1,await one.RecoverExpiredLeases(default));Assert.Equal("RETRY_SCHEDULED",(await State(cs,lease)).Status);Assert.True(await new OutboxProcessor(new PostgresOutboxStoreV2(source,b),new PilotOutboxHandler()).Tick());var state=await State(cs,fail);Assert.Equal("DEAD_LETTER",state.Status);Assert.Equal("PARTNER_ADAPTER_NOT_CONFIGURED",state.Error);}
 static async Task Seed(string cs,Guid id,string tenant,string type,string status,int minutes){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO outbox_messages(id,organization_id,type,payload,correlation_id,attempt,next_attempt_at,status,created_at) VALUES($1,$2::uuid,$3,'{}',$4,0,now()+$5::interval,$6,now()+$5::interval)";q.Parameters.AddWithValue(id);q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(type);q.Parameters.AddWithValue($"v2-{id:N}");q.Parameters.AddWithValue(TimeSpan.FromMinutes(minutes));q.Parameters.AddWithValue(status);await q.ExecuteNonQueryAsync();}static async Task<(string Status,string? Error)> State(string cs,Guid id){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT status,error_code FROM outbox_messages WHERE id=$1";q.Parameters.AddWithValue(id);await using var r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());return(r.GetString(0),r.IsDBNull(1)?null:r.GetString(1));}
}
